import {startRuntime,describe} from './dist/host/loader.js';
let rt=null, stopped=false;
const post=(type,data={})=>self.postMessage({type,...data});
function hasRepeatedTail(text){if(typeof text!=='string'||text.length<24)return false;const tail=text.slice(-2048);for(let n=2;n<=32;n++){if(tail.length<n*12)break;const unit=tail.slice(-n);if(unit.trim().length&&tail.endsWith(unit.repeat(12)))return true}return false}
function hasRepeatedLines(text){if(typeof text!=='string')return false;const lines=text.split(/\r?\n/).map(x=>x.trim().replace(/\s+/g,' ').toLocaleLowerCase()).filter(Boolean);if(lines.length<12)return false;const last=lines[lines.length-1];return last.length>=3&&lines.slice(-12).every(x=>x===last)}
self.onmessage=async({data})=>{try{if(data.type==='load'){const manifestText=await (await fetch(new URL('../manifest-model.json',import.meta.url))).text();const manifest=JSON.parse(manifestText);const started=await startRuntime({distUrl:new URL('./dist/',import.meta.url),glueName:'paddle_ocr_runtime',threads:data.threads,onWarning:message=>post('warning',{message})});post('runtime',{build:started.build.name,threads:started.threads});rt=new started.glue.Runtime(manifestText);const dir=data.dir;let done=0,total=manifest.parts.reduce((a,p)=>a+p.bytes,0);for(let i=0;i<manifest.parts.length;i++){let p=manifest.parts[i],file;if(p.file.startsWith('parts/')){const d=await dir.getDirectoryHandle('parts');file=await (await d.getFileHandle(p.file.slice(6))).getFile()}else file=await (await dir.getFileHandle(p.file)).getFile();if(file.size!==p.bytes)throw Error('File model không đủ dữ liệu: '+p.file);let reader=file.stream().getReader();while(true){let {value,done:end}=await reader.read();if(end)break;rt.write_part(i,value);done+=value.length;post('progress',{done,total})}rt.end_part(i);post('verified',{part:i+1,totalParts:manifest.parts.length})}post('ready');}else if(data.type==='read'){if(!rt)throw Error('Chưa nạp model');stopped=false;const plan=JSON.parse(rt.start(data.rgba,data.width,data.height,JSON.stringify({task:'ocr'})));post('started',{job:data.job,plan});let lastSent=0,lastStage,firstTokenSent=false,steps=0,messages=0,lastText;while(true){await new Promise(r=>setTimeout(r,0));if(stopped){rt.cancel();post('done',{job:data.job,stopped:true,steps,messages});break}const p=JSON.parse(rt.step());steps++;if(p.text!==undefined)lastText=p.text;else if(p.done&&lastText!==undefined)p.text=lastText;if(!p.done&&data.loopGuard&&(hasRepeatedLines(lastText)||hasRepeatedTail(lastText))){rt.cancel();messages++;post('done',{...p,job:data.job,text:lastText,done:true,truncated:true,reason:'repeated_lines',steps,messages});break}const now=performance.now(),firstToken=p.tokens>0&&!firstTokenSent,stageChanged=p.stage!==lastStage;if(p.done||!data.throttle||stageChanged||firstToken||now-lastSent>=200){messages++;post(p.done?'done':'text',{job:data.job,...p,steps,messages});lastSent=now;lastStage=p.stage;if(p.tokens>0)firstTokenSent=true}if(p.done)break}}else if(data.type==='stop'){stopped=true}}catch(e){post('error',{message:describe(e),job:data.job})}};
